Here is the commit message:
net: macb: remove unnecessary code

Commit 653e92a9175e ("net: macb: add support for padding and fcs
computation") introduced a bug fixed by commit 899ecaedd155 ("net:
ethernet: cadence: fix socket buffer corruption problem"). Code removed
in this patch is not reachable at all so remove it.

Fixes: 653e92a9175e ("net: macb: add support for padding and fcs computation")
Cc: Tristram Ha <Tristram.Ha@microchip.com>
Signed-off-by: Claudiu Beznea <claudiu.beznea@microchip.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The bug was introduced due to unnecessary and unreachable code added in a previous commit, which complicated the logic for padding and FCS computation, leading to potential socket buffer corruption. The removed code was not executed under any conditions, indicating it was redundant and could mislead developers about the intended functionality.

Here is the patch:

 static int macb_pad_and_fcs(struct sk_buff **skb, struct net_device *ndev)
 {
 	bool cloned = skb_cloned(*skb) || skb_header_cloned(*skb);
 	int padlen = ETH_ZLEN - (*skb)->len;
 	int headroom = skb_headroom(*skb);
 	int tailroom = skb_tailroom(*skb);
 	struct sk_buff *nskb;
 	u32 fcs;

 	if (!(ndev->features & NETIF_F_HW_CSUM) ||
 	    !((*skb)->ip_summed != CHECKSUM_PARTIAL) ||
 	    skb_shinfo(*skb)->gso_size)	/* Not available for GSO */
 		return 0;

 	if (padlen <= 0) {
 		/* FCS could be appeded to tailroom. */
 		if (tailroom >= ETH_FCS_LEN)
 			goto add_fcs;
 		/* FCS could be appeded by moving data to headroom. */
 		else if (!cloned && headroom + tailroom >= ETH_FCS_LEN)
 			padlen = 0;
 		/* No room for FCS, need to reallocate skb. */
 		else
 			padlen = ETH_FCS_LEN;
 	} else {
 		/* Add room for FCS. */
 		padlen += ETH_FCS_LEN;
 	}

 	if (!cloned && headroom + tailroom >= padlen) {
 		(*skb)->data = memmove((*skb)->head, (*skb)->data, (*skb)->len);
 		skb_set_tail_pointer(*skb, (*skb)->len);
 	} else {
 		nskb = skb_copy_expand(*skb, 0, padlen, GFP_ATOMIC);
 		if (!nskb)
 			return -ENOMEM;

 		dev_kfree_skb_any(*skb);
 		*skb = nskb;
 	}

-	if (padlen) {
-		if (padlen >= ETH_FCS_LEN)
-			skb_put_zero(*skb, padlen - ETH_FCS_LEN);
-		else
-			skb_trim(*skb, ETH_FCS_LEN - padlen);
-	}
+	if (padlen > ETH_FCS_LEN)
+		skb_put_zero(*skb, padlen - ETH_FCS_LEN);

 add_fcs:
 	/* set FCS to packet */
 	fcs = crc32_le(~0, (*skb)->data, (*skb)->len);
 	fcs = ~fcs;

 	skb_put_u8(*skb, fcs		& 0xff);
 	skb_put_u8(*skb, (fcs >> 8)	& 0xff);
 	skb_put_u8(*skb, (fcs >> 16)	& 0xff);
 	skb_put_u8(*skb, (fcs >> 24)	& 0xff);

 	return 0;
 }



